(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,90856,e=>{"use strict";var t=e.i(43476),s=e.i(56420);let n={name:"download",size:24,node:[["path",{d:"M12 15V3",key:"m9g1x1"}],["path",{d:"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4",key:"ih7n3h"}],["path",{d:"m7 10 5 5 5-5",key:"brsn70"}]]};n.node;let i=(0,s.f)(n);var a=e.i(3348);e.s(["CopyMarkdown",0,function({markdown:e,filename:s}){let n=`data:text/markdown;charset=utf-8,${encodeURIComponent(e)}`;return(0,t.jsxs)("div",{className:"flex flex-wrap items-center gap-2",children:[(0,t.jsx)(a.CopyButton,{value:e,label:"Copy page as Markdown"}),(0,t.jsxs)("a",{href:n,download:s,className:"inline-flex min-h-11 min-w-11 items-center justify-center gap-1.5 rounded-md border border-border bg-background/80 px-2.5 py-1 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",children:[(0,t.jsx)(i,{className:"size-3.5","aria-hidden":"true"}),"Download .md"]})]})}],90856)},44913,e=>{"use strict";var t=e.i(43476),s=e.i(56420);let n={name:"chevron-down",size:24,node:[["path",{d:"m6 9 6 6 6-6",key:"qrunsl"}]]};n.node;let i=(0,s.f)(n),a={name:"list-tree",size:24,node:[["path",{d:"M8 5h13",key:"1pao27"}],["path",{d:"M13 12h8",key:"h98zly"}],["path",{d:"M13 19h8",key:"c3s6r1"}],["path",{d:"M3 10a2 2 0 0 0 2 2h3",key:"1npucw"}],["path",{d:"M3 5v12a2 2 0 0 0 2 2h3",key:"x1gjn2"}]]};a.node;let o=(0,s.f)(a);var r=e.i(22016);let d={slug:"cli",title:"CLI reference",summary:"Fourteen commands, five global flags, and exit codes a script can branch on.",blocks:[{kind:"code",label:"Usage",code:`ccresu [--config PATH] [--json] [--log-level LEVEL] <command> [flags]
ccresu --help | --version`},{kind:"capture",id:"help"},{kind:"h2",text:"Global flags"},{kind:"table",head:["Flag","Meaning"],rows:[["-c, --config PATH","Configuration file. Default: ~/.config/ccresu/config.yaml; `CCRESU_CONFIG` overrides the default, `--config` overrides both."],["--json","Machine-readable output where the command supports it."],["--log-level LEVEL","debug, info, warn or error."],["--log-format FMT","json or text."],["-v, --verbose","Shorthand for --log-level debug."],["-q, --quiet","Shorthand for --log-level error."]]},{kind:"p",text:"The configuration file is chosen in this order, first match wins: `-c/--config PATH`, then `CCRESU_CONFIG` in the environment, then `$XDG_CONFIG_HOME/ccresu/config.yaml` (else `~/.config/ccresu/config.yaml`). A leading `~` is expanded, and paths derived from the file — such as the API token beside it — follow the file actually in use."},{kind:"h2",text:"Commands"},{kind:"table",head:["Command","What it does"],rows:[["daemon","Run the watchdog loop until interrupted. `--once` runs a single reconcile pass; `--interval` overrides the reconcile interval."],["status","Summarise configuration path, database, session counts, pending recoveries, schedules and Telegram state. Its `sessions` line is the total row count; its `listing` line says how many a bare `sessions` shows."],["sessions","List discovered sessions. A bare listing is enabled only and says so in the footer; `--all` includes disabled and settled ones, `--state` filters (repeatable), `--limit` caps the output and says when it truncated."],["sessions status <session-id>","Show everything known about one session: identity, state, schedule, attempts and recent transitions. `inspect <session-id>` is the same command."],["sessions delete <session-id>","Remove the session from ccresu — its row, attempts, transitions, usage limits, pending wait and notifications. Nothing under ~/.claude is touched; a tombstone keeps discovery from re-creating it, and `enable <session-id>` undoes the delete."],["inspect <session-id>","Alias of `sessions status`."],["recover <session-id>","Resume one session now. `--force` ignores a spent attempt budget; `--message` overrides the continuation message."],["retry <session-id>","Spend one attempt now instead of waiting for the next discovery pass."],["enable <session-id>","Allow ccresu to recover a session. Also the undo for `sessions delete`: the tombstone is cleared and the row re-created before it is enabled."],["disable <session-id>","Stop ccresu from recovering a session without forgetting its history."],["history <session-id>","Print the state transitions and attempts; `--limit` caps how many are shown."],["config init","Write the shipped example configuration to the resolved path with mode 0600. `--force` replaces an existing file; without it the command refuses and writes nothing."],["config validate","Validate the file, the environment overrides and every default."],["config show","Print the effective configuration with secrets redacted."],["doctor","Check the config, timezone, data directory, database schema, Claude Code CLI, transcript access, Telegram and discovery."],["serve","Run the REST + SSE API. `--addr HOST:PORT` overrides `server.host:server.port`."],["version","Print version, commit and build date."]]},{kind:"h2",text:"Exit codes"},{kind:"table",head:["Code","Meaning"],rows:[["0","Success."],["1","Failure: the operation ran and did not succeed."],["2","Usage error: unknown command, unknown flag or bad arguments."],["3","Not found: no such session."],["4","Not eligible: the session exists but cannot be recovered right now."],["130","Interrupted (SIGINT)."]]},{kind:"h2",text:"Examples"},{kind:"code",label:"A typical session",code:`ccresu status
ccresu sessions --state WAITING_FOR_RESET
ccresu inspect 4d1f9c2a-... 
ccresu history 4d1f9c2a-... --limit 20
ccresu recover 4d1f9c2a-... --force
ccresu --json sessions | jq '.[].id'`},{kind:"note",tone:"info",title:"A background session is stopped, not abandoned",text:"When `claude -p --resume` refuses because the session is still attached to Claude Code's background agent (`That session is running in the background (837eaaea) …`), ccresu runs `claude stop <job-id>` — the eight lower-case hex job name the refusal itself prints (`837eaaea`), not the session UUID; `claude stop` resolves job names only and answers a UUID with `No job matching` and exit 1 — and repeats the identical resume once inside the same attempt. The conversation is kept — same session id, same transcript — and the stop is logged rather than recorded as the attempt's command. If the stop fails, or the second resume refuses again, the original error is reported unchanged."},{kind:"note",tone:"info",title:"Session counts: total vs listed",text:"`ccresu status` counts every stored session row; a bare `ccresu sessions` lists only the enabled ones. Both say so: `status` prints `sessions: 27 total, 1 enabled` followed by `listing: ccresu sessions shows the 1 enabled; ccresu sessions --all shows all 27`, and the listing footer reads `1 session(s) shown: enabled only (of 27 matching; --all includes disabled and settled)`. A `--limit` that truncates adds `limit N reached; use --limit 0 to list every match`. `status --json` exposes `sessions` (total), `enabled_sessions` and `sessions_listed_by_default`, the last matching what a bare `sessions --json` returns."},{kind:"capture",id:"status"},{kind:"capture",id:"sessions"},{kind:"note",tone:"info",title:"Global flags go anywhere",text:"Global flags are accepted before or after the command name: `ccresu --json status` and `ccresu status --json` are the same invocation, and flags may be interleaved with positionals (`ccresu recover <id> --json`). A flag value is never mistaken for a global flag, so `ccresu recover <id> --message --json` sends the text `--json`. `ccresu <command> --help` lists every flag that command accepts, global ones included."}]};var c=e.i(66065);let l={slug:"configuration",title:"Configuration",summary:"One YAML file, validated at startup, with environment variables that always win.",blocks:[{kind:"p",text:`ccresu reads \`${c.f.config}\` by default, or the path given with \`--config\`. The full annotated example lives in \`configs/config.example.yaml\`; every field in it is validated, and an invalid value is a startup error rather than a silent fallback.`},{kind:"p",text:"Resolution order, first match wins: `--config PATH` (or `-c PATH`), then the `CCRESU_CONFIG` environment variable, then the default path. A leading `~` is expanded in all three, and everything derived from the file — such as the API token beside it — follows the file actually in use."},{kind:"h2",text:"Environment overrides"},{kind:"p",text:"Every field can be overridden with a `CCRESU_` prefixed variable: upper-case the section and field, and join nesting with a double underscore. The environment always takes precedence over the file, which keeps secrets out of it."},{kind:"code",label:"Environment",code:`CCRESU_APP__LOG_LEVEL=debug
CCRESU_RECOVERY__MAX_ATTEMPTS=5
CCRESU_TELEGRAM__BOT_TOKEN=123456:...
CCRESU_SERVER__PORT=8787

ccresu config validate`},{kind:"h2",text:"Sections"},{kind:"table",head:["Section","What it controls"],rows:[["app","Log level and format, and the IANA timezone used for display."],["claude","Executable name, discovery interval, extra monitored sessions, and the continuation message sent on resume."],["monitoring","Which detections are on: usage limits distinguish from session completion."],["detector","Confidence threshold and custom regular expressions for phrasings ccresu does not know yet."],["scheduler","Poll interval, and the exponential backoff used when a limit message carries no reset time."],["recovery","Attempt budget, backoff with jitter, startup and verification timeouts, and the concurrency limit."],["telegram","Bot token, chat id, parse mode and one switch per notification event."],["server","Loopback host, port, and the browser origins allowed to make read-only requests."],["storage","SQLite path and busy timeout."]]},{kind:"h2",text:"Detection patterns"},{kind:"p",text:"Custom patterns are Go regular expressions matched against normalised text: lower-cased, single-spaced, with curly quotes and dashes folded to ASCII. A rule can require a reset time and carries its own confidence, which is compared with `detector.threshold`."},{kind:"code",label:"Teaching ccresu a new phrasing",code:`detector:
  threshold: 0.5
  custom_patterns:
    - id: internal-proxy-limit
      kind: five_hour        # five_hour | weekly | other
      pattern: 'proxy quota exhausted'
      confidence: 0.9
      requires_reset: false
      description: our corporate proxy reports the limit differently`},{kind:"h2",text:"Recovery tuning"},{kind:"table",head:["Field","Default","Meaning"],rows:[["max_attempts","10","Resume attempts before a session is marked DISCOVERED."],["initial_delay","30s","First retry delay after a failed attempt."],["max_delay","15m","Ceiling for the exponential backoff."],["multiplier","2.0","Growth factor between attempts."],["jitter","0.15","Random fraction added so retries do not synchronise."],["startup_timeout","60s","How long a resume process may take to start producing output."],["verification_timeout","120s","How long the verifier waits for the transcript to grow."],["max_concurrent_recoveries","3","Recovery loops allowed to run at once."]]},{kind:"h2",text:"Showing the effective configuration"},{kind:"code",label:"Validate, then print",code:`ccresu config init          # write the shipped example, mode 0600, never overwriting
ccresu config init --force  # replace an existing file with the shipped example
ccresu config validate      # exits non-zero on the first invalid field
ccresu config show          # effective values after defaults and env overrides
ccresu --json config show   # the same, as JSON`},{kind:"note",tone:"warning",title:"Secrets",text:"Prefer `CCRESU_TELEGRAM__BOT_TOKEN` over writing the token into the file, and keep the file readable only by you: `chmod 600 ~/.config/ccresu/config.yaml`. The API never returns the token, and logs redact it."}]},h={slug:"deployment",title:"Deployment",summary:"Run ccresu as a user-level systemd service, or under any supervisor that can restart a process.",blocks:[{kind:"p",text:"ccresu is a long-running foreground process. It needs no privileges, writes only under your home directory, and handles SIGTERM by finishing its current step and releasing the database and the API port."},{kind:"h2",text:"systemd (user unit)"},{kind:"code",label:"~/.config/systemd/user/ccresu.service",code:`[Unit]
Description=ccresu — resume Claude Code sessions after a usage limit resets
Documentation=https://github.com/jymchng/ccresu
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=%h/.local/bin/ccresu daemon
Restart=on-failure
RestartSec=10
Environment=CCRESU_APP__LOG_FORMAT=json

[Install]
WantedBy=default.target`},{kind:"code",label:"Enable it",code:`systemctl --user daemon-reload
systemctl --user enable --now ccresu.service
systemctl --user status ccresu.service
loginctl enable-linger "$USER"   # keep it running while you are logged out`},{kind:"note",tone:"warning",title:"The daemon needs your Claude Code credentials",text:"Run the daemon as the user who owns `~/.claude`. A system-wide unit running as another user, or as root, will not see the sessions it is supposed to recover."},{kind:"h2",text:"Running the API"},{kind:"p",text:"`ccresu serve` starts the REST + SSE API. It binds `127.0.0.1` unless the configuration says otherwise (`:8787` is promoted to `127.0.0.1:8787`, so a bare port cannot expose it by accident), and it writes a bearer token with mode 0600 on first start, beside the configuration file in use (`~/.config/ccresu/api-token` by default, `/elsewhere/api-token` with `--config /elsewhere/config.yaml`). Expose it beyond loopback only through a reverse proxy you control, and keep the token out of browser-visible code."},{kind:"h2",text:"Upgrading"},{kind:"ol",items:["Stop the daemon: `systemctl --user stop ccresu`.","Download and verify the new release asset, replacing `~/.local/bin/ccresu`.","Run `ccresu doctor` to confirm the database schema and the Claude Code CLI are readable.","Start the daemon again and check `ccresu status`."]},{kind:"p",text:"The database is migrated forward automatically on start. Back up `~/.local/share/ccresu/ccresu.db` before a downgrade, since older binaries reject a newer schema."},{kind:"h2",text:"Other supervisors"},{kind:"ul",items:["macOS: a launchd `LaunchAgent` running the same `ccresu daemon` command.","Windows: a Task Scheduler task set to run at logon with `ccresu daemon`.","Containers: mount `~/.claude` and the data directory as volumes, and run the daemon in the foreground; the SQLite driver is pure Go, so there is no libc dependency.","Supervisors that stop the process with SIGKILL skip the graceful shutdown; the state machine is crash-safe, so the next start reconciles the stale attempt."]}]};var u=e.i(469);let m={slug:"recovery",title:"How recovery works",summary:"From the limit banner to a verified resume, through an explicit persisted state machine.",blocks:[{kind:"p",text:"A recovery is a chain of recorded state transitions, not a fire-and-forget command. Each transition is validated against an edge table before it is written, so an impossible step is an error rather than a corrupted history."},{kind:"code",label:"The happy path",code:`DISCOVERED -> RUNNING -> USAGE_LIMIT_DETECTED -> WAITING_FOR_RESET
  -> RESET_TIME_REACHED -> CHECKING_SESSION -> CHECKING_LIMIT
  -> RESUMING -> RESUMED`},{kind:"h2",text:"Off the happy path"},{kind:"table",head:["State","When it is recorded"],rows:[["RETRY_WAIT","An attempt failed and the budget still has room, or the pre-resume check failed and no attempt was spent; the loop returns to CHECKING_SESSION after a backoff."],["DISCOVERED","The attempt budget is spent, or a resume attempt failed with an error classified as non-retryable."],["COMPLETED","The session finished normally before the limit, so there is nothing to resume."],["USER_TERMINATED","The user cancelled the session."],["DISABLED","Recovery was switched off with `ccresu disable`."],["UNRECOVERABLE","The session type or the observed error cannot be resumed with the documented CLI."]]},{kind:"diagram",id:"state-machine",label:"The chain, the retry loop and the two ways out",description:"The solid line is the recorded chain: discovery, the detected limit, the wait, the reset instant, the session check, the limit check and the resume. The dashed line is a failed attempt with budget left, which returns to the session check after a backoff. An attempt that fails with the budget spent, or with an error classed as non-retryable, ends in DISCOVERED; `ccresu retry <id>` is the only operator edge from there, and it lands in DISABLED."},{kind:"h2",text:"What “resume” actually runs"},{kind:"p",text:"ccresu uses five verified interfaces: discovery (`claude agents --json`), the session transcript and per-session environment directories under `~/.claude`, the resume command below, and `claude stop <job-id>` for one narrow case. Nothing else is invoked, and no new session is ever started in place of the original one."},{kind:"code",label:"The resume command",code:'claude -p --resume <session-id> --output-format json "<continuation message>"'},{kind:"ul",items:["`-p` (print mode) because the process is not attached to a terminal: ccresu never sends keystrokes and never allocates a pty.","`--resume <session-id>` so the original conversation continues instead of a new one starting.","The continuation message defaults to a request to continue the existing active goal, and can be overridden per session.","The command runs in the session's recorded working directory, so relative paths and project configuration still apply."]},{kind:"h2",text:"Why the message is the last argument"},{kind:"p",text:"The prompt is a positional argument: no flag introduces it. Position is the only thing that says which invocation it belongs to, and the documented form is `claude -p --resume <session-id> <prompt>`, so the message follows the session it is said to. ccresu keeps it last, after both flags, and builds the vector in one place."},{kind:"code",label:"internal/claude/cli.go",code:`func ResumeArgs(sessionID, message string) []string {
	return []string{"-p", "--resume", sessionID, "--output-format", "json", message}
}`},{kind:"ul",items:["`TestResumeArgsExact` asserts the joined vector, so a reordering is a failing test rather than a puzzling runtime refusal.","`Resume` hands the same slice to the first attempt and to the repeat after `claude stop`, so the second invocation cannot be a subtly different command.","The attempt's `command` column, rendered by `commandPreview`, prints the same order: `claude -p --resume <session-id> --output-format json <N-byte continuation message>`, with the placeholder where the message really sits.","Only a summary is stored, never the text: the column says how many bytes were sent, and the conversation stays in the transcript."]},{kind:"note",tone:"info",title:"Why the audit trail has to match",text:"`ccresu history` is an audit trail. The preview used to print the flags after the `<message>` placeholder, describing an invocation ccresu never ran — worse than no preview, because it looks authoritative. It now renders exactly the order `claude.ResumeArgs` executes."},{kind:"h2",text:"When a background agent still holds the session"},{kind:"p",text:"`claude -p --resume` refuses outright while the same session is attached to the interactive CLI's background agent: the CLI answers `That session is running in the background (837eaaea). Run claude attach 837eaaea to open it, or claude stop 837eaaea first to resume it here. Add --fork-session to branch off a copy instead.` Nothing about the conversation is lost there, so it must not end the session's life."},{kind:"ol",items:["The refusal is recognised after normalisation — ANSI colour codes stripped, indentation and line wrapping collapsed — so a restyled message still matches, and an unrelated failure is not mistaken for this one.","`claude stop <job-id>` releases the background agent. The job name is the eight lower-case hex name this very refusal prints (`837eaaea`), never the session UUID: `claude stop` resolves job names only and answers a UUID with `No job matching` and exit 1. A refusal that names no job is not stopped at all — guessing could stop another session's agent. The stop is written to the log, never to the attempt row: `ccresu history` still shows the one resume command that was run.","The identical resume is issued once more — same arguments, same session id, same continuation message — and its result becomes the attempt's result. It is not a second try against the budget: the attempt keeps its number."]},{kind:"table",head:["Step","What the CLI sees","What ccresu records"],rows:[["1",'`claude -p --resume <id> --output-format json "<message>"` — refused, the session is in the background',"the attempt, with its single resume command as `command`"],["2","`claude stop <job-id>` — eight hex characters, never the session UUID","a log line only: the attempt row still shows one resume"],["3","the same resume, byte-identical arguments","the attempt's result, verification included"]]},{kind:"diagram",id:"stop-then-resume",label:"One attempt, three calls",description:"The resume is refused because the session is still attached to the background agent. ccresu runs `claude stop <job-id>`, then issues the identical resume with the same arguments, inside the same attempt. That second result becomes the attempt's result, and RESUMED is written only after verification."},{kind:"note",tone:"warning",title:"Stopped once, and only once",text:"If the stop itself fails, or the second resume refuses again (or fails any other way), the original error is returned untouched: nothing loops and the classification is unchanged. `--fork-session` is still never used — it would continue a copy of the conversation — and `claude attach` needs a terminal ccresu does not have, which is exactly why `stop` is the one remedy taken. A session stopped this way resumes normally next time, because the background agent no longer holds it."},{kind:"h2",text:"The operator exit from DISCOVERED"},{kind:"p",text:"A session that ended `DISCOVERED` this way — or any other way — is not lost. `ccresu retry <session-id>` is how an operator says so, and it is deliberately narrow."},{kind:"ul",items:["It moves `DISCOVERED` to `DISABLED` and nothing else: any other state is refused with exit code `4` and a message that names the state and the command to use instead.","It clears the stored error, so the session no longer looks broken.","It keeps the attempt row, its reason and the counter, so `ccresu history` still explains what happened.","It never resumes anything and never refunds an attempt. `ccresu retry <id>` refills the budget, `ccresu recover <id> --force` tries once more now, and `ccresu enable <id>` makes the session recoverable again with whatever budget it has left."]},{kind:"h2",text:"Proving it end to end"},{kind:"p",text:"This is not only asserted against fakes. `make e2e` runs `tests/scripts/background-resume-e2e.sh`, which builds the real binary and puts a stub `claude` on `PATH`. The stub keeps a background-agent marker, refuses the first `-p --resume` with the CLI's text above, clears the marker on `claude stop <job-id>`, and then returns a JSON result with the same `session_id` after growing the transcript. The stub resolves its argument the way the real CLI does — only an eight-hex job name it holds, anything else answered with `No job matching` and exit 1 — so a stop that carried the session UUID fails there exactly as it does in the field. The run asserts that `ccresu recover <id>` exits 0 and ends `RESUMED` with the verification “proven: session id preserved and transcript grew”, that the stub saw exactly resume, stop, resume with byte-identical resume arguments, and that `ccresu history` still records the single resume command. One more assertion closes the gap the field found: the stop carried the job name and never the session UUID."},{kind:"code",label:"The contrast, against the pre-fix commit",code:`make e2e                              # the fixed binary: every check passes

git worktree add /tmp/ccresu-prefix 00692e3
(cd /tmp/ccresu-prefix && go build -o /tmp/ccresu-prefix/ccresu ./cmd/ccresu)
tests/scripts/background-resume-e2e.sh --pre-fix /tmp/ccresu-prefix/ccresu`},{kind:"capture",id:"e2e"},{kind:"table",head:["Binary","`ccresu recover <id>`","Stub saw","Final state"],rows:[["before the fix (`00692e3`)","exits 1, reporting the refusal","one resume, no stop","`DISCOVERED`"],["with the fix","exits 0, verification proven","resume, stop, resume","`RESUMED`"]]},{kind:"p",text:"The failing session in the same run is also the fixture for `ccresu retry`: `DISCOVERED` becomes `DISABLED`, the session's stored error is cleared, the attempt row and its reason are kept, a second `reset` is refused with exit 4, and `ccresu enable` leaves the session recoverable again."},{kind:"h2",text:"Verification"},{kind:"p",text:"A process starting proves nothing: Claude Code may exit immediately, or may create a new conversation. After the resume, the verifier waits up to `recovery.verification_timeout` for two facts:"},{kind:"ol",items:["The session id still exists in discovery and is the same id that was interrupted.","The transcript for that id grew: the conversation continued instead of being recreated."]},{kind:"note",tone:"info",title:"Why both checks",text:"The id proves the conversation was resumed rather than forked; the transcript growth proves the resume actually produced work. Only then is RESUMED written and the success notification sent."},{kind:"h2",text:"Waiting for the reset"},{kind:"p",text:"The reset time is parsed out of the limit message itself. `resets 12pm (Europe/Berlin)` becomes noon in Berlin, stored as a UTC instant with the original timezone kept for display, and the wait is unaffected by the host timezone or by a DST change in between. When the message carries no reset time, ccresu polls with exponential backoff starting at `scheduler.unknown_reset_initial_interval` (5m) up to `unknown_reset_max_interval` (30m)."},{kind:"h2",text:"Restarts and duplicate prevention"},{kind:"ul",items:["Sessions, schedules and attempts are persisted, so a restart or reboot resumes waiting with the original deadline.","One recovery loop per session is enforced by a per-session lock, so two triggers cannot resume the same session twice.","Transitions are idempotent: re-observing a state that is already recorded does not add a duplicate row.","A crash mid-attempt leaves a stale attempt that the next pass reconciles before starting a new one."]},{kind:"h2",text:"Observing a recovery"},{kind:"code",label:"Follow one session",code:`ccresu inspect <session-id>        # state, schedule, attempts
ccresu history <session-id>        # every recorded transition
curl -N http://127.0.0.1:8787/api/v1/events   # live SSE feed`},{kind:"capture",id:"history"}]},p={slug:"security",title:"Security",summary:"Loopback-only API, a token for every write, no terminal automation and no telemetry.",blocks:[{kind:"p",text:"ccresu runs on the machine that has your Claude Code credentials, so its threat model is the local one: another user on the box, a browser page you happened to open, and anything that can read your home directory."},{kind:"h2",text:"How the resume is executed"},{kind:"ul",items:['Exactly one command is ever built: `claude -p --resume <session-id> --output-format json "<message>"`, with the session id and message passed as separate arguments, never through a shell.',"No pty is allocated and no keystrokes are injected, so ccresu cannot type into a terminal you are using.","A session id is validated before use, so a crafted id cannot become a flag or a path traversal.","The API has no endpoint that executes a command: recovery goes through the recovery manager, and settings are validated configuration fields.","No new session is ever started in place of the original one."]},{kind:"h2",text:"API protections"},{kind:"table",head:["Control","Behaviour"],rows:[["Binding",`Defaults to \`${c.j.address}\`; a bare \`:port\` is rewritten to loopback.`],["Authentication",`Every state-changing request needs \`Authorization: Bearer <token>\` from \`${c.j.tokenFile}\` (mode 0600, created on first start, constant-time comparison).`],["CSRF","The token is read only from the Authorization header, never from a cookie or a query parameter, so a cross-site request cannot supply it; there is no session cookie to ride on."],["Origins","Browser requests from an origin outside `server.allowed_origins` are rejected with 403, including preflight."],["Rate limits","Per-client token buckets, with a hard cap on the bucket table, and `Retry-After` on 429."],["Size limits","Request bodies are capped, and a mutating request must be JSON with the right content type."],["Headers","`nosniff`, frame-deny, no-referrer, a restrictive Content-Security-Policy, and a panic in a handler becomes a 500 instead of a crash."],["Redaction","The API returns the configuration and Telegram state with the bot token redacted, and never returns the API token."]]},{kind:"h2",text:"Local files"},{kind:"ul",items:["`~/.config/ccresu/config.yaml` may hold the Telegram bot token: keep it 0600, or use the environment instead.","`~/.config/ccresu/api-token` (beside the configuration file in use) is created 0600 and tightened back to 0600 if it was copied around with looser permissions.","`~/.local/share/ccresu/ccresu.db` holds session ids, project paths, schedules and attempt history: it references your work but never stores conversation content.","Logs are structured JSON (or text) with secrets redacted before they are written."]},{kind:"h2",text:"What ccresu never does"},{kind:"ul",items:["It sends nothing to a third party except the Telegram messages you enabled.","It ships no embedded web UI: the binary serves only the JSON/SSE API.","It does not bypass or work around Anthropic usage limits, it only waits for the documented reset.","It does not read files outside the Claude Code directories it needs."]},{kind:"h2",text:"Reporting a vulnerability"},{kind:"p",text:"Open a private security advisory on the repository rather than a public issue, and include the version from `ccresu version`."}]},f={slug:"telegram",title:"Telegram notifications",summary:"Optional, deduplicated, off the recovery path: a Telegram outage can never block a resume.",blocks:[{kind:"h2",text:"Create a bot and find the chat"},{kind:"ol",items:["Talk to @BotFather, run `/newbot`, and copy the token it returns.","Send the bot a message so the chat exists.","Read your chat id from `curl https://api.telegram.org/bot<token>/getUpdates` (the `chat.id` field), or use a public id such as `@channelname` for a channel."]},{kind:"h2",text:"Configure"},{kind:"code",label:"Prefer the environment for the token",code:`export CCRESU_TELEGRAM__BOT_TOKEN="123456:ABC-DEF..."

# ~/.config/ccresu/config.yaml
telegram:
  enabled: true
  chat_id: "123456789"
  parse_mode: HTML
  notify_limit_detected: true
  notify_waiting: false
  notify_recovery_started: true
  notify_recovery_success: true
  notify_recovery_failure: true
  notify_permanent_failure: true
  notify_session_completed: true`},{kind:"p",text:"`ccresu doctor` reports `telegram disabled` or `telegram configured`, and the API exposes the same state at `GET /api/v1/telegram/status` with the token redacted."},{kind:"h2",text:"Events"},{kind:"table",head:["Event","Sent when"],rows:[["limit detected","A usage-limit banner was matched and recorded."],["waiting","The session is waiting for its reset time (off by default: it is the noisiest event)."],["recovery started","A resume attempt is about to run."],["recovery success","The resume was verified: same session id, longer transcript."],["recovery failure","An attempt failed and another one is scheduled."],["permanent failure","The attempt budget is spent or the error is not retryable."],["session completed","The session finished normally, so no recovery is needed."]]},{kind:"h2",text:"Delivery behaviour"},{kind:"ul",items:["Messages are HTML-escaped: a project path or session id containing `<` or `&` cannot break the message or inject markup.","The templates are HTML, so `parse_mode: HTML` is the only accepted value; `MarkdownV2` and `Markdown` are rejected at config validation rather than arriving as literal markup.","HTTP 429 responses honour `retry_after`, and transient failures retry with backoff.","Delivery state is persisted per event, so the same event is not sent twice across restarts.","Sending happens off the recovery path: a slow or failing Telegram API cannot delay or fail a resume.","The bot token is redacted from every log line and error message, including request errors that embed the URL."]},{kind:"note",tone:"warning",title:"Bot tokens are credentials",text:"Anyone with the token can post as your bot. Keep it in the environment or a 0600 file, and revoke it with @BotFather if it leaks. ccresu never logs it and never returns it from the API."}]},g={slug:"troubleshooting",title:"Troubleshooting",summary:"Diagnose with doctor, inspect and history, then match the symptom.",blocks:[{kind:"h2",text:"Start with the two diagnostic commands"},{kind:"code",label:"Environment and per-session state",code:`ccresu doctor
ccresu inspect <session-id>
ccresu history <session-id> --limit 50`},{kind:"p",text:"`doctor` checks the configuration, timezone, data directory, database schema version, the Claude Code CLI version, transcript readability, Telegram and discovery. `inspect` shows what ccresu believes about one session; `history` shows every transition it recorded."},{kind:"h2",text:"Symptoms"},{kind:"table",head:["Symptom","Likely cause and fix"],rows:[["`sessions: 0` in status","Discovery found nothing: check that `claude agents --json` works as your user, then run `ccresu doctor` and look at the `claude` and `transcripts` rows."],["The limit message was seen but no session is waiting","The banner scored below `detector.threshold`, or the wording is unknown. Add a `detector.custom_patterns` rule, or lower the threshold and re-run `ccresu config validate`."],["Waiting for a reset time that looks wrong","The message's own timezone wins over the host timezone, and a message without one falls back to polling. Check `ccresu inspect` for the timezone it parsed and the deadline it stored."],["`state: DISCOVERED`","The attempt budget is spent or the error was classified as non-retryable. `ccresu history` shows the classified error; `ccresu retry <session-id>` resets the budget once the cause is fixed."],["`state: UNRECOVERABLE`","The session type or the observed error cannot be resumed through `claude -p --resume`. This is reported instead of inventing an undocumented command."],["Recovery ran but the transcript did not grow","The resume process started and exited without producing work. The verifier refuses to record RESUMED; check the recorded error and the resumes' output in the logs."],["Exit code 2","Usage error: an unknown flag, or a flag that command does not define. Global flags work before or after the command name; `ccresu <command> --help` lists the command's flags."],["Exit code 3","No such session id. `ccresu sessions --all` lists every id ccresu knows."],["Exit code 4","The session exists but is not eligible: it is disabled, already resumed, or its reset time has not arrived."],["The API returns 401","The request changes state and needs `Authorization: Bearer <token>`. Read the token from `~/.config/ccresu/api-token`; it is not the Telegram token."],["The API returns 403","The browser Origin is not in `server.allowed_origins`. Add it, or call the API from a script, which sends no Origin."],["The API returns 429","The rate limit was hit. Wait for the `Retry-After` seconds, or reduce the request rate."],["Telegram messages never arrive","Check `ccresu doctor` for the Telegram row, the event switches in the configuration, and the chat id; a wrong chat id is rejected by the Bot API."],["`database is locked`","Another process holds a long write. Ensure only one daemon runs per database, and consider raising `storage.busy_timeout`."]]},{kind:"h2",text:"Reading the logs"},{kind:"code",label:"Debug logging as JSON",code:`ccresu --log-level debug --log-format json daemon
systemctl --user status ccresu
journalctl --user -u ccresu -n 100 --no-pager`},{kind:"p",text:"Every line is a structured record with a stable level and message; secrets are redacted before the line is written, so a token never appears in the output."},{kind:"h2",text:"Resetting state"},{kind:"note",tone:"warning",title:"Deleting the database forgets every schedule",text:"The database is the only record of pending recoveries. Back it up before deleting it: `cp ~/.local/share/ccresu/ccresu.db ~/ccresu.db.bak`, then stop the daemon first so the WAL is flushed."},{kind:"p",text:"For a single session, prefer `ccresu retry` (reset the attempt budget), `ccresu retry` (clear a rediscovered session, leaving it disabled), `ccresu enable`/`disable` (stop recovery without forgetting history), or `ccresu recover --force` (try again now) over deleting state."}]},b={slug:"tutorial",title:"Tutorial: your first recovered session",summary:"Thirteen steps from an empty machine to a session that was resumed for you, then the same state driven by hand and over the API.",blocks:[{kind:"p",text:"Every command below is real output from the binary run on a scratch HOME, so paths and session IDs are examples — yours will differ. Install ccresu first (see Installation), and make sure `claude` is on PATH with at least one session under `~/.claude/projects`."},{kind:"note",tone:"info",title:"Global flags go before the command",text:"`--config PATH` selects a configuration file other than `~/.config/ccresu/config.yaml` (so does `CCRESU_CONFIG` in the environment), and `--json` switches a command to machine-readable output. Both are global flags: `ccresu --config ./test.yaml sessions`, not `ccresu sessions --config ./test.yaml`."},{kind:"h2",text:"Step 1 — Create the configuration"},{kind:"p",text:"`config init` writes the example configuration the binary carries — the same bytes the installer copies — to the default path, readable only by you."},{kind:"code",label:"Create the configuration",code:`$ ccresu config init
configuration /home/you/.config/ccresu/config.yaml created (mode 0600)

Next steps:
  1. edit /home/you/.config/ccresu/config.yaml
  2. ccresu config validate
  3. ccresu doctor`},{kind:"p",text:"The default path is `~/.config/ccresu/config.yaml`; `XDG_CONFIG_HOME` moves it, and the global `--config PATH` flag, the `CCRESU_CONFIG` environment variable or a positional argument names the file explicitly. Parent directories are created and the file is 0600. An existing file is never replaced silently — that is exit code 1 with the file untouched:"},{kind:"code",label:"Explicit paths, and the refusal",code:`ccresu --config /tmp/ccresu/config.yaml config init
ccresu config init /tmp/ccresu/config.yaml

$ ccresu config init
ccresu: configuration /home/you/.config/ccresu/config.yaml already exists; it was left untouched
to keep it:          edit it, then run 'ccresu config validate'
to replace it:       ccresu config init /home/you/.config/ccresu/config.yaml --force
to use another file: ccresu --config PATH config init

ccresu config init --force   # replace it with the shipped example
ccresu --json config init    # path, created, replaced, mode, valid, next_steps`},{kind:"h2",text:"Step 2 — Validate the configuration"},{kind:"p",text:"ccresu reads one YAML file. Every field is validated before anything runs, so a typo is a startup error rather than a silent default."},{kind:"code",label:"Validate",code:`$ ccresu config validate
configuration /home/you/.config/ccresu/config.yaml is valid
app:           ccresu
timezone:      Asia/Singapore
database:      /home/you/.local/share/ccresu/ccresu.db
monitoring:    yes
recovery:      yes (max attempts 10)
telegram:      no
server:        yes (127.0.0.1:8787)

$ ccresu config validate ./configs/config.example.yaml   # an explicit path
$ ccresu config show                                    # effective values`},{kind:"h2",text:"Step 3 — Check the environment"},{kind:"p",text:"`ccresu doctor` is the pre-flight check: the config, the timezone, the data directory, the database schema, the Claude Code CLI, transcript access, Telegram and discovery."},{kind:"code",label:"Doctor",code:`$ ccresu doctor
STATUS  CHECK           DETAIL
ok      config          /home/you/.config/ccresu/config.yaml
ok      timezone        Asia/Singapore
ok      data directory  /home/you/.local/share/ccresu
ok      database        /home/you/.local/share/ccresu/ccresu.db (schema version 4)
ok      claude          claude 2.0.30 (claude --version)
ok      transcripts     session transcripts are readable
ok      telegram        disabled
warn    sessions        no sessions discovered yet`},{kind:"p",text:'A `fail` row exits 1; `warn` does not. `doctor --json` returns `{"checks": [...]}` with the same names and statuses.'},{kind:"h2",text:"Step 4 — Run the watchdog"},{kind:"code",label:"Daemon, or the API",code:`$ ccresu daemon        # discovers on claude.discovery_interval and reconciles
$ ccresu daemon --once # a single reconcile pass, then exit 0

$ ccresu serve
ccresu API listening on 127.0.0.1:8787`},{kind:"p",text:"For a long-lived install, run the daemon as a service (see Deployment). `ccresu serve [--addr HOST:PORT]` defaults to `server.host`/`server.port` and is the scripting route used in step 13."},{kind:"h2",text:"Step 5 — Find your sessions"},{kind:"code",label:"sessions --all",code:`$ ccresu sessions --all
SESSION   STATE       NEXT ATTEMPT                    ENABLED  RECOVERABLE  PROJECT                 LAST SEEN                NOTE
1dd41fc3  DISCOVERED  none (session is not enabled)   no       yes                                   2026-11-05 03:24:03 +08
4a52c0c7  DISCOVERED  none (session is not enabled)   no       yes                                   2026-11-05 03:24:03 +08
88dfd995  DISCOVERED  none (session is not enabled)   no       yes                                   2026-11-05 03:24:03 +08
e1732e3d  DISCOVERED  none (session is not enabled)   no       yes                                   2026-11-05 03:24:03 +08
e60a3100  DISCOVERED  none (no usage limit detect...  yes      yes          /home/you/projects/demo 2026-11-05 03:24:03 +08

5 session(s) shown (--all: disabled and settled sessions included)`},{kind:"ul",items:["`SESSION` is the first eight characters of the session ID; commands need the full ID.","`STATE` is the state-machine position — DISCOVERED, WAITING_FOR_RESET, RESUMING, RESUMED, RETRY_WAIT, DISCOVERED and so on.","`NEXT ATTEMPT` is when ccresu will touch the row and why: `in 2h14m` while a wait is pending, `none (<reason>)` when nothing is scheduled.","`RECOVERABLE` and `NOTE` explain why a session is or is not actionable."]},{kind:"p",text:"Without `--all` the table shows only the enabled sessions, which is a different number from the total `ccresu status` counts, so the footer says which filter is in force and what it hides. A `--limit` that truncates adds `limit N reached; use --limit 0 to list every match`."},{kind:"code",label:"The default listing states its filter",code:`$ ccresu sessions
no enabled sessions match; 5 match with --all

$ ccresu sessions
SESSION   STATE              NEXT ATTEMPT  ENABLED  RECOVERABLE  PROJECT                 LAST SEEN                NOTE
3f9d1c07  WAITING_FOR_RESET  in 1m20s      yes      yes          /home/you/projects/demo 2026-11-05 03:43:40 +08
1 session(s) shown: enabled only (of 5 matching; --all includes disabled and settled)`},{kind:"h2",text:"Step 6 — Allow recovery of a session"},{kind:"p",text:"Recovery is opt-in per session: discovery records everything, but ccresu only resumes what you enable. Disabling is honoured immediately and is not the same as forgetting the session — the row stays, its history stays, and `--state DISABLED` still lists it."},{kind:"code",label:"enable / disable",code:`$ ccresu enable 3f9d1c07-1111-4222-8333-444455556666
session 3f9d1c07-1111-4222-8333-444455556666: enabled=yes

$ ccresu disable 3f9d1c07-1111-4222-8333-444455556666
session 3f9d1c07-1111-4222-8333-444455556666: enabled=no`},{kind:"h2",text:"Step 7 — Inspect one session"},{kind:"p",text:"`inspect` is the verbose view: identity, paths, when the next attempt is due and why, the latest detected limit, the stored schedule and the recent transitions. The Next attempt block comes first because it is the question you opened `inspect` to answer. The ID must be complete; a truncated UUID is `not found` with exit code 3."},{kind:"code",label:"inspect",code:`$ ccresu inspect 3f9d1c07-1111-4222-8333-444455556666
session:       3f9d1c07-1111-4222-8333-444455556666
state:         WAITING_FOR_RESET
enabled:       yes
recoverable:   yes
project:       /home/you/projects/demo
transcript:    /home/you/.claude/projects/-home-you-projects-demo/3f9d1c07-1111-4222-8333-444455556666.jsonl
type:          unknown
last seen:     2026-11-05 03:28:16 +08

Next attempt
at:            2026-11-04 19:29:00 UTC (in 45s)
why:           waiting for the usage limit to reset

Latest usage limit
type:          five_hour
detected:      2026-11-05 03:28:16 +08
resets:        2026-11-05 03:29:00 +08
raw:           7:29pm (UTC)
confidence:    0.99

Schedule
due:           2026-11-05 03:29:00 +08
unknown reset: no
polls:         0
phrase:        7:29pm (UTC)

Recent transitions
WHEN                     TRANSITION                                 REASON
2026-11-05 03:28:16 +08  DISCOVERED -> USAGE_LIMIT_DETECTED         usage limit detected in the transcript
2026-11-05 03:28:16 +08  USAGE_LIMIT_DETECTED -> WAITING_FOR_RESET  waiting until 2026-11-04T19:29:00Z`},{kind:"code",label:"Getting the full ID",code:"ccresu --json sessions --all | jq -r '.[].ID'"},{kind:"p",text:"`inspect --json` carries the same answer as `next_attempt.at` (RFC 3339), `next_attempt.reason` and a ready-made `next_attempt.human` countdown."},{kind:"h2",text:"Step 8 — Watch a usage limit be detected and scheduled"},{kind:"p",text:"Nothing to do here but leave the daemon running and let a session hit its limit. When the banner appears in a transcript, the daemon logs it and moves the session to WAITING_FOR_RESET with a schedule. `--log-format text` makes the log line readable in a terminal; `json` is the default."},{kind:"code",label:"The detection log line",code:'{"time":"2026-11-04T19:28:16.224107958Z","level":"INFO","msg":"usage limit detected","session":"3f9d1c07-1111-4222-8333-444455556666","limit":"five_hour","known_reset":true,"reset_at":"2026-11-04T19:29:00Z"}'},{kind:"code",label:"The table and the summary pick it up",code:`$ ccresu sessions
SESSION   STATE              NEXT ATTEMPT  ENABLED  RECOVERABLE  PROJECT                 LAST SEEN                NOTE
3f9d1c07  WAITING_FOR_RESET  in 1m20s      yes      yes          /home/you/projects/demo 2026-11-05 03:43:40 +08

1 session(s) shown: enabled only (--all includes disabled and settled)

$ ccresu status
config:        /home/you/.config/ccresu/config.yaml
database:      /home/you/.local/share/ccresu/ccresu.db
sessions:      1 total, 1 enabled
listing:       ccresu sessions shows the 1 enabled; ccresu sessions --all shows all 1
pending:       1
schedules:     1
next wake:     2026-11-04T19:29:00Z
telegram:      no
recovery:      yes (max attempts 10)
now:           2026-11-05 03:28:16 +08

STATE              SESSIONS
WAITING_FOR_RESET  1`},{kind:"p",text:"`next wake` is the moment the daemon will act, in UTC. If the reset time could not be extracted from the banner, the session is still scheduled: ccresu polls with a backoff (`scheduler.unknown_reset_initial_interval` up to `scheduler.unknown_reset_max_interval`) until the limit clears, and `inspect` shows `unknown reset: yes`."},{kind:"h2",text:"Step 9 — Watch the resume happen"},{kind:"p",text:"When the reset time arrives, ccresu re-checks the session, checks that the limit has actually cleared, resumes the same session ID, and verifies the conversation grew afterwards. `ccresu history` is the audit trail; `--limit N` caps how many transitions are shown (default 50, newest kept)."},{kind:"code",label:"history",code:`$ ccresu history 3f9d1c07-1111-4222-8333-444455556666
session:       3f9d1c07-1111-4222-8333-444455556666
state:         RESUMED

#  STATE    STARTED                  FINISHED                 RESULT     ERROR
1  RESUMED  2026-11-05 03:29:03 +08  2026-11-05 03:29:03 +08  succeeded

WHEN                     TRANSITION                                 REASON
2026-11-05 03:28:16 +08  DISCOVERED -> USAGE_LIMIT_DETECTED         usage limit detected in the transcript
2026-11-05 03:28:16 +08  USAGE_LIMIT_DETECTED -> WAITING_FOR_RESET  waiting until 2026-11-04T19:29:00Z
2026-11-05 03:29:03 +08  WAITING_FOR_RESET -> RESET_TIME_REACHED    the scheduled reset time has arrived
2026-11-05 03:29:03 +08  RESET_TIME_REACHED -> CHECKING_SESSION     checking the session before resuming
2026-11-05 03:29:03 +08  CHECKING_SESSION -> CHECKING_LIMIT         checking the usage limit has cleared
2026-11-05 03:29:03 +08  CHECKING_LIMIT -> RESUMING                 resuming the original session
2026-11-05 03:29:03 +08  RESUMING -> RESUMED                        the original session resumed and the conversation grew`},{kind:"h2",text:"Step 10 — Act manually"},{kind:"p",text:"Four commands bypass the wait, with different rules: `recover` resumes now (still respecting the attempt budget), `recover --force` tries even when the budget is spent, `retry` gives a spent or terminal session a fresh budget, and `reset` clears a rediscovered session into `DISABLED` without refunding an attempt."},{kind:"code",label:"recover / retry / reset",code:`ccresu recover 3f9d1c07-1111-4222-8333-444455556666
ccresu recover <id> --message "Pick up where the limit interrupted you." --force
ccresu retry <id>
ccresu retry <id>`},{kind:"p",text:"`recover` refuses when the session cannot be resumed, and says why. Exit code 4 means not eligible; 3 means not found."},{kind:"code",label:"A refusal, verbatim",code:`$ ccresu recover 3f9d1c07-1111-4222-8333-444455556666
ccresu: recover 3f9d1c07-1111-4222-8333-444455556666: recovery: session is not eligible for recovery: session 3f9d1c07-1111-4222-8333-444455556666 is RESUMED and cannot become CHECKING_SESSION
$ echo $?
4

$ ccresu recover e60a3100-123a-4deb-b146-54705ff80268
ccresu: recover e60a3100-123a-4deb-b146-54705ff80268: recovery: invalid state transition: DISCOVERED -> CHECKING_SESSION (legal targets: DISABLED, DISCOVERED, RUNNING, UNRECOVERABLE)`},{kind:"h2",text:"Step 11 — When the resume fails"},{kind:"p",text:"Failures are retried with exponential backoff, and every attempt is numbered against `recovery.max_attempts`. The delays come from `recovery.initial_delay` (30s), `recovery.multiplier` (2.0), `recovery.max_delay` (15m) and `recovery.jitter` (0.15), which is why the values are not exactly 30s, 60s, 2m. Between attempts the session sits in RETRY_WAIT and the wait is a stored instant, not just prose."},{kind:"code",label:"The budget being spent",code:`2026-11-05 03:27:03 +08  RESUMING -> RETRY_WAIT  attempt 1/10 failed (retryable); next attempt in 28.99625...
2026-11-05 03:27:03 +08  RESUMING -> RETRY_WAIT  attempt 2/10 failed (retryable); next attempt in 1m4.2447...

$ ccresu sessions
SESSION   STATE       NEXT ATTEMPT  ENABLED  RECOVERABLE  PROJECT                 LAST SEEN                NOTE
3f9d1c07  RETRY_WAIT  in 58s        yes      yes          /home/you/projects/demo 2026-11-05 03:45:04 +08  resume session 3f9d1c07-1111-4222-833...

$ ccresu inspect 3f9d1c07-1111-4222-8333-444455556666 | head -13
...
Next attempt
at:            2026-11-04 19:46:02 UTC (in 58s)
why:           retrying after a failed attempt`},{kind:"code",label:"When the budget is exhausted",code:`$ ccresu sessions --all
SESSION   STATE               NEXT ATTEMPT                    ENABLED  RECOVERABLE  PROJECT                 LAST SEEN                NOTE
7c1b2a44  DISCOVERED  none (attempt budget spent;...  yes      yes          /home/you/projects/demo 2026-11-05 03:28:24 +08  resume session 7c1b2a44-0000-4000-800...

$ ccresu retry 7c1b2a44-0000-4000-8000-abcdefabcdef
ccresu: retry 7c1b2a44-0000-4000-8000-abcdefabcdef: recovery: session 7c1b2a44-0000-4000-8000-abcdefabcdef ended in DISCOVERED: resume session 7c1b2a44-0000-4000-8000-abcdefabcdef: claude: malformed claude output: empty resume output`},{kind:"p",text:"`reset` is the way out that does not spend an attempt: it accepts only `DISCOVERED`, drops the stored error, and parks the session as `DISABLED`. It never resumes, and the attempt history and counter are untouched (`retry` is what refills the budget). Any other state is refused with exit code 4 and a message naming what to use instead; exit 3 means no such session, 2 means a bad argument."},{kind:"code",label:"Clearing the failure",code:`$ ccresu retry 7c1b2a44-0000-4000-8000-abcdefabcdef
session:       7c1b2a44-0000-4000-8000-abcdefabcdef
state:         DISABLED
previous state: DISCOVERED
error:         cleared
attempts:      kept (use 'ccresu retry' to spend another)
session 7c1b2a44-0000-4000-8000-abcdefabcdef: reset; run 'ccresu enable 7c1b2a44-0000-4000-8000-abcdefabcdef' to let ccresu recover it again`},{kind:"note",tone:"info",title:"A background session is stopped, not abandoned",text:"One failure is not the session's fault at all: `claude -p --resume` refuses while the session is still attached to Claude Code's background agent (`That session is running in the background (837eaaea) …`). ccresu treats that as busy, not gone: in the same attempt it runs `claude stop <job-id>` (the eight-hex job name the refusal prints, never the session id) and repeats the identical resume once, so the session reaches RESUMED without intervention and the conversation is kept — same session id, same transcript. The stop is logged, not recorded as the attempt's command. If the stop fails or the second resume refuses again, the original error is reported unchanged and the session lands in DISCOVERED, which is where `retry`, `reset` and `recover --force` come in."},{kind:"h2",text:"Step 12 — Turn on Telegram notifications (optional)"},{kind:"p",text:"Off by default; recovery never depends on it. Put the token in the environment so it stays out of backups and shell history, and the chat in the configuration file."},{kind:"code",label:"Configuration",code:`export CCRESU_TELEGRAM__BOT_TOKEN='123456789:AA...'

# config.yaml
telegram:
  enabled: true
  chat_id: "-1001234567890"
  parse_mode: HTML`},{kind:"code",label:"Confirm both halves are seen — the token is masked",code:`$ ccresu config validate
configuration /home/you/.config/ccresu/config.yaml is valid
telegram:      yes
$ ccresu doctor
ok      telegram        chat -1001234567890, token ********abcd`},{kind:"p",text:"Each event is a separate switch (`notify_limit_detected`, `notify_recovery_started`, `notify_recovery_success`, `notify_recovery_failure`, `notify_permanent_failure`, `notify_session_completed`, and `notify_waiting` which defaults to false). Delivery is queued in SQLite by a sender goroutine, so a slow Telegram cannot delay a resume."},{kind:"h2",text:"Step 13 — Script it: the REST and SSE API"},{kind:"p",text:"`ccresu serve` exposes the same state over HTTP on 127.0.0.1:8787 under `/api/v1`. Read-only routes need no credentials; state-changing routes want a bearer token, generated on first start beside the configuration file in use — `~/.config/ccresu/api-token` by default, `/elsewhere/api-token` after `--config /elsewhere/config.yaml` — with mode 0600 (or wherever `server.token_path` points)."},{kind:"code",label:"The API",code:`$ ccresu serve
ccresu API listening on 127.0.0.1:8787

$ curl -s localhost:8787/api/v1/health
{"api":"/api/v1","now":"2026-11-04T19:24:45.110691574Z","status":"ok","uptime_seconds":3.033467921}

TOKEN=$(cat ~/.config/ccresu/api-token)
curl -s localhost:8787/api/v1/sessions
curl -s localhost:8787/api/v1/sessions/$ID
curl -s localhost:8787/api/v1/sessions/$ID/history
curl -s -X POST -H "Authorization: Bearer $TOKEN" localhost:8787/api/v1/sessions/$ID/enable
curl -s -X POST -H "Authorization: Bearer $TOKEN" localhost:8787/api/v1/sessions/$ID/disable
curl -s -X POST -H "Authorization: Bearer $TOKEN" \\
  -d '{"message":"continue the goal"}' localhost:8787/api/v1/sessions/$ID/recover

$ curl -s -o /dev/null -w '%{http_code}\\n' -X POST localhost:8787/api/v1/sessions/$ID/enable
401`},{kind:"p",text:"For a live feed, subscribe to the SSE stream. It opens with a `retry:` hint and a ready event, then pushes state changes, so a script can react without polling."},{kind:"code",label:"SSE",code:`$ curl -N localhost:8787/api/v1/events
retry: 3000

event: ready
data: {"type":"ready","at":"2026-11-04T19:24:46.122116919Z","data":{"api":"/api/v1","heartbeat_seconds":15}}`},{kind:"h2",text:"Where to go next"},{kind:"ul",items:["CLI reference — every command, flag and exit code.","Configuration — every setting, its default and its environment override.","Recovery — detection, scheduling and the state machine.","Deployment — running the daemon as a service.","Troubleshooting — symptom-to-cause tables."]}]},y=[function(e=c.$){let t=(0,c.B)(e,"linux","amd64"),s=(0,c.B)(e,"darwin","arm64"),n=(0,c.B)(e,"windows","amd64");return{slug:"installation",title:"Installation",summary:"Install a released binary with a single line, or build from source with Go 1.26 or newer.",blocks:[{kind:"p",text:`Releases are published on the GitHub releases page (${c.a.releases}). Each tag carries one archive per supported platform plus a \`checksums.txt\` with the SHA-256 of every asset, and the installer verifies the checksum before it extracts anything.`},{kind:"h2",text:"Install with one line"},{kind:"p",text:"Linux and macOS, `amd64` or `arm64`: the installer detects the platform, resolves the newest release, downloads that archive and `checksums.txt`, verifies the hash, installs the binary into `~/.local/bin` and writes `~/.config/ccresu/config.yaml`."},{kind:"code",label:"Linux and macOS",code:(0,u.b)("unix")},{kind:"p",text:"Preview it first if you prefer: the dry run prints every action and downloads nothing."},{kind:"code",label:"Preview, changes nothing",code:(0,u.b)("unixPreview")},{kind:"p",text:`Pin a release by putting the version in the same line. The one on this page is \`${e}\`, the newest published release when the page was built.`},{kind:"code",label:`Pinned to ${e}`,code:(0,u.b)("unixPinned",e)},{kind:"h2",text:"Install on Windows"},{kind:"p",text:"The PowerShell installer does the same work in a normal, non-elevated window: it verifies the sha256 of the `.zip` before extracting it, installs `ccresu.exe` under `%LOCALAPPDATA%`, adds that directory to your user `PATH` and writes `%APPDATA%\\ccresu\\config.yaml`."},{kind:"code",label:"Windows, PowerShell",code:(0,u.b)("windows")},{kind:"code",label:`Windows, pinned to ${e}`,code:(0,u.b)("windowsPinned",e)},{kind:"p",text:`The installers are short and readable, and you should read what you pipe into a shell: [scripts/install.sh](${c.a.url}/blob/main/scripts/install.sh) and [scripts/install.ps1](${c.a.url}/blob/main/scripts/install.ps1). Re-running the same line is the supported upgrade path.`},{kind:"note",tone:"info",title:"Asset naming",text:`Assets are named \`ccresu_<version>_<os>_<arch>.tar.gz\` (\`.zip\` on Windows), for example \`${t}\`, \`${s}\` and \`${n}\`. Supported targets: linux and darwin on amd64 and arm64, windows on amd64 and arm64. The installers pick the matching one for the machine they run on.`},{kind:"h2",text:"Install with Go"},{kind:"p",text:"The SQLite driver is pure Go, so the build needs no cgo and no system SQLite library. The line below installs into `$(go env GOPATH)/bin` and prints the version it produced."},{kind:"code",label:"Go 1.26 or newer",code:(0,u.b)("go")},{kind:"h2",text:"Build from source"},{kind:"code",label:"Clone, build, run",code:(0,u.b)("source")},{kind:"h2",text:"First run"},{kind:"ol",items:["Create `~/.config/ccresu/config.yaml` with `ccresu config init`, then edit it. The installers write it for you already.","Run `ccresu config validate` to check the file, the environment overrides and every default.","Run `ccresu doctor` to check the Claude Code CLI, transcript access, the database and the data directory.","Start the watchdog with `ccresu daemon`, or install it as a service (see Deployment)."]},{kind:"p",text:"ccresu creates its SQLite database at `~/.local/share/ccresu/ccresu.db` and, if the API is enabled, a bearer token with mode 0600 beside the configuration file in use (`~/.config/ccresu/api-token` for the default configuration). Neither is created until it is needed."},{kind:"h2",text:"Requirements"},{kind:"ul",items:["Claude Code installed and logged in: discovery runs `claude agents --json`, so `claude` must be on PATH.","Read access to `~/.claude/projects` and `~/.claude/session-env` for transcript-based detection and verification.","No root privileges: everything lives under your home directory, and the installer refuses to run as root.",`The raw scripts the two lines above pipe into a shell: \`${u.B.unix}\` and \`${u.B.windows}\`.`]}]}}(c.$),b,l,d,m,f,h,p,g,{slug:"limitations",title:"Known limitations",summary:"What ccresu deliberately does not do, and where it can still be defeated.",blocks:[{kind:"p",text:"This project is honest about its boundaries: it resumes work after a documented usage limit, and it reports what it cannot do rather than guessing."},{kind:"h2",text:"Scope"},{kind:"ul",items:["It does not lift, reset or bypass usage limits. It waits for the reset time the message reports, and nothing more.","It cannot resume a session type the CLI cannot resume. Such a session is marked UNRECOVERABLE and left alone.","It resumes in print mode (`claude -p --resume`), so the resumed work continues non-interactively. If you want to keep typing in that conversation, attach to it yourself afterwards.","It is a local tool: one machine, one user, one home directory. Session discovery reads that machine's Claude Code state.","It ships no web dashboard. The interfaces are the CLI and the REST/SSE API, and this site is documentation only."]},{kind:"h2",text:"Detection"},{kind:"ul",items:["Unknown phrasings are not detected until you add a custom pattern. The built-in rules cover the canonical banners; prose about limits is guarded against, but a very unusual wording can still be missed.","When a message carries no reset time, ccresu cannot know the deadline: it polls with backoff until the limit is gone, which means the resume can happen later than the real reset.","A reset time is only as good as the message: if Claude Code reports it in a timezone the parser does not recognise, the session falls back to polling."]},{kind:"h2",text:"Verification"},{kind:"ul",items:["Verification depends on transcript growth. If Claude Code changes where or how it writes transcripts, verification fails safe: the session is not marked RESUMED.","Transcript growth proves the conversation continued; it cannot prove the model finished the original goal."]},{kind:"h2",text:"Operational"},{kind:"ul",items:["The daemon must keep running; a machine that is asleep or off at the reset time recovers on the next start, not at the exact moment.","One database per user: two daemons sharing a database will serialise on SQLite writes and can delay each other.","The API trusts the local user. Anything that can read your home directory can read the bearer token, so loopback binding and file permissions are the real boundary.","Notifications are best-effort: a Telegram outage delays messages, and they are retried, but delivery is not guaranteed."]},{kind:"note",tone:"info",title:"Reporting a limitation",text:"If a real Claude Code message is not detected, open an issue with the observed banner (redact session ids) so it can become a built-in pattern instead of a local customisation."}]}];var v=e.i(47163);function w({activeSlug:e}){return(0,t.jsxs)("nav",{"aria-label":"Documentation",className:"flex flex-col gap-1",children:[(0,t.jsx)("p",{className:"px-2 pb-1 text-xs font-semibold uppercase tracking-wide text-muted-foreground",children:"Documentation"}),y.map(s=>{let n=s.slug===e;return(0,t.jsx)(r.default,{href:`/docs/${s.slug}/`,"aria-current":n?"page":void 0,className:(0,v.f)("flex min-h-11 items-center rounded-md px-2 text-sm transition-colors",n?"bg-accent font-medium text-accent-foreground":"text-muted-foreground hover:bg-accent/60 hover:text-accent-foreground"),children:s.title},s.slug)})]})}var k=e.i(79988);e.s(["DocsMenu",0,function({activeSlug:e}){return(0,t.jsx)("div",{className:"lg:hidden",children:(0,t.jsx)(k.MobileDisclosure,{label:"documentation menu",trigger:(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)("span",{className:"flex items-center gap-2",children:[(0,t.jsx)(o,{className:"size-4","aria-hidden":"true"}),"Documentation menu"]}),(0,t.jsx)(i,{className:"size-4","aria-hidden":"true"})]}),buttonClassName:"flex min-h-11 w-full items-center justify-between gap-2 rounded-xl border border-border bg-card px-3 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent",panelClassName:"mt-2",innerClassName:"rounded-xl border border-border bg-card p-2",children:(0,t.jsx)(w,{activeSlug:e})})})}],44913)}]);